import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { MAX_NPM_AUDIT_JSON_BUFFER, runNpmAuditJson, } from '../npmSecurityAudit.js';
/* eslint-disable @typescript-eslint/no-require-imports */
const { mockExecFile } = vi.hoisted(() => {
    const { promisify } = require('node:util');
    const pCustom = promisify.custom;
    const fn = vi.fn();
    fn[pCustom] = (command, args, options) => {
        return new Promise((resolve, reject) => {
            fn(command, args, options, (err, s, s2) => {
                if (err) {
                    return reject(err);
                }
                resolve({ stdout: s, stderr: s2 });
            });
        });
    };
    return { mockExecFile: fn };
});
vi.mock('node:child_process', () => ({
    execFile: mockExecFile,
}));
const noopChildProcess = {};
describe('runNpmAuditJson', () => {
    const auditRoot = path.join(os.tmpdir(), `uie-npm-audit-${Date.now()}`);
    const pkgPath = path.join(auditRoot, 'package.json');
    const lockPath = path.join(auditRoot, 'package-lock.json');
    beforeEach(() => {
        vi.mocked(mockExecFile).mockReset();
        fs.mkdirSync(auditRoot, { recursive: true });
        fs.writeFileSync(pkgPath, JSON.stringify({ name: 'fixture', version: '1.0.0' }));
        fs.writeFileSync(lockPath, JSON.stringify({ name: 'fixture', lockfileVersion: 3 }));
    });
    afterEach(() => {
        fs.rmSync(auditRoot, { recursive: true, force: true });
    });
    it('returns skipped when package.json is missing', async () => {
        const root = path.join(os.tmpdir(), `uie-no-pkg-${Date.now()}`);
        fs.mkdirSync(root, { recursive: true });
        try {
            const result = await runNpmAuditJson(root);
            expect(result.skipped).toBe(true);
            expect(vi.mocked(mockExecFile)).not.toHaveBeenCalled();
        }
        finally {
            fs.rmSync(root, { recursive: true, force: true });
        }
    });
    it('returns skipped when package-lock.json is missing', async () => {
        const root = path.join(os.tmpdir(), `uie-no-lock-${Date.now()}`);
        fs.mkdirSync(root, { recursive: true });
        fs.writeFileSync(path.join(root, 'package.json'), JSON.stringify({ name: 'fixture', version: '1.0.0' }));
        try {
            const result = await runNpmAuditJson(root);
            expect(result.skipped).toBe(true);
            expect(vi.mocked(mockExecFile)).not.toHaveBeenCalled();
        }
        finally {
            fs.rmSync(root, { recursive: true, force: true });
        }
    });
    it('returns stdout on exit 0', async () => {
        const json = '{"metadata":{"vulnerabilities":{"total":0}}}';
        vi.mocked(mockExecFile).mockImplementation((_cmd, _args, _opts, callback) => {
            const cb = callback;
            cb(null, json, '');
            return noopChildProcess;
        });
        const result = await runNpmAuditJson(auditRoot);
        expect(result.skipped).toBe(false);
        expect(result.exitCode).toBe(0);
        expect(result.source).toBe(json);
        expect(vi.mocked(mockExecFile)).toHaveBeenCalledWith('npm', ['audit', '--json'], expect.objectContaining({
            cwd: auditRoot,
            encoding: 'utf8',
            maxBuffer: MAX_NPM_AUDIT_JSON_BUFFER,
            shell: true,
        }), expect.any(Function));
    });
    it('runs npm through a shell so `npm.cmd` resolves on Windows', async () => {
        vi.mocked(mockExecFile).mockImplementation((_cmd, _args, opts, callback) => {
            const cb = callback;
            if (!opts.shell) {
                const notFound = new Error('spawn npm ENOENT');
                notFound.code = 'ENOENT';
                cb(notFound);
                return noopChildProcess;
            }
            cb(null, '{"metadata":{"vulnerabilities":{"total":0}}}', '');
            return noopChildProcess;
        });
        const result = await runNpmAuditJson(auditRoot);
        expect(result.skipped).toBe(false);
        expect(result.exitCode).toBe(0);
        expect(result.source).toBe('{"metadata":{"vulnerabilities":{"total":0}}}');
    });
    it('returns stdout on non-zero when npm prints audit JSON (vulnerabilities)', async () => {
        const json = JSON.stringify({
            metadata: { vulnerabilities: { total: 1, high: 1 } },
        });
        vi.mocked(mockExecFile).mockImplementation((_cmd, _args, _opts, callback) => {
            const cb = callback;
            const err = {
                name: 'Error',
                message: 'audit found issues',
                code: 1,
                stdout: json,
            };
            cb(err, json, '');
            return noopChildProcess;
        });
        const result = await runNpmAuditJson(auditRoot);
        expect(result.skipped).toBe(false);
        expect(result.source).toBe(json);
        expect(result.exitCode).toBe(1);
    });
    it('returns synthetic JSON when exec fails with no stdout (ENOENT-style)', async () => {
        vi.mocked(mockExecFile).mockImplementation((_cmd, _args, _opts, callback) => {
            const cb = callback;
            const notFound = new Error('spawn failed');
            notFound.code = 'ENOENT';
            cb(notFound);
            return noopChildProcess;
        });
        const result = await runNpmAuditJson(auditRoot);
        expect(result.skipped).toBe(false);
        const parsed = JSON.parse(result.source);
        expect(parsed.error.code).toBe('ENOENT');
    });
    it('returns synthetic JSON when stdout exceeds maxBuffer (ERR_CHILD_PROCESS_STDIO_MAXBUFFER)', async () => {
        vi.mocked(mockExecFile).mockImplementation((_cmd, _args, _opts, callback) => {
            const cb = callback;
            const err = new Error('maxBuffer exceeded');
            err.code = 'ERR_CHILD_PROCESS_STDIO_MAXBUFFER';
            cb(err);
            return noopChildProcess;
        });
        const result = await runNpmAuditJson(auditRoot);
        expect(result.skipped).toBe(false);
        const parsed = JSON.parse(result.source);
        expect(parsed.error.code).toBe('ERR_CHILD_PROCESS_STDIO_MAXBUFFER');
    });
});
